var (
	Groups_CreateGroupTool   = newTool("groups-create_group_v1", `Creates a group. POST /v1/groups body: the group itself Members may be supplied at creation, unlike the LDAP lineage where a group and its memberships are two calls. Server-assigned fields on the request body are ignored. Not idempotent. Retrying after a timeout may create a second group; supply `+"`"+`group_id`+"`"+` if the caller needs retry safety. ALREADY_EXISTS     that group_id is taken INVALID_ARGUMENT   a field violates its buf.validate constraint PERMISSION_DENIED  caller may not create here`, Groups_CreateGroupSchemaJSON, Groups_CreateGroupOutputSchemaJSON, nil, "", nil)
	Groups_DeleteGroupTool   = newTool("groups-delete_group_v1", `Deletes a group. DELETE /v1/{name=groups/*} Soft delete: the group is marked deleted, disappears from List unless `+"`"+`show_deleted`+"`"+` is set, and is purged at `+"`"+`expire_time`+"`"+`. Its members are not deleted -- a membership is an edge, and removing the group removes the edges with it. NOT_FOUND          no such group ABORTED            etag does not match PERMISSION_DENIED  caller may not delete it`, Groups_DeleteGroupSchemaJSON, Groups_DeleteGroupOutputSchemaJSON, nil, "", nil)
	Groups_GetGroupTool      = newTool("groups-get_group_v1", `Retrieves one group. GET /v1/{name=groups/*} Safe and idempotent. NOT_FOUND          no such group, or it is soft-deleted and `+"`"+`show_deleted`+"`"+` was not set INVALID_ARGUMENT   name does not match groups/* PERMISSION_DENIED  caller may not read it`, Groups_GetGroupSchemaJSON, Groups_GetGroupOutputSchemaJSON, nil, "", nil)
	Groups_ListGroupsTool    = newTool("groups-list_groups_v1", `Lists groups. GET /v1/groups Paginated per AIP-158. Page tokens are opaque and may expire. INVALID_ARGUMENT   malformed filter, or page_size out of range PERMISSION_DENIED  caller may not list this collection`, Groups_ListGroupsSchemaJSON, Groups_ListGroupsOutputSchemaJSON, nil, "", nil)
	Groups_UndeleteGroupTool = newTool("groups-undelete_group_v1", `Restores a soft-deleted group. POST /v1/{name=groups/*}:undelete Valid only before `+"`"+`expire_time`+"`"+`; after that the group is gone and this returns NOT_FOUND. NOT_FOUND          no such group, or already purged ALREADY_EXISTS     the group is not deleted PERMISSION_DENIED  caller may not restore it`, Groups_UndeleteGroupSchemaJSON, Groups_UndeleteGroupOutputSchemaJSON, nil, "", nil)
	Groups_UpdateGroupTool   = newTool("groups-update_group_v1", `Updates a group. PATCH /v1/{group.name=groups/*} body: the group itself A partial update: only fields named in `+"`"+`update_mask`+"`"+` are written. Naming `+"`"+`members`+"`"+` replaces the list wholesale; see UpdateGroupRequest.update_mask. Idempotent. Pass the `+"`"+`etag`+"`"+` read from Get to make the write conditional. NOT_FOUND          no such group ABORTED            etag does not match the stored resource INVALID_ARGUMENT   mask names an unknown or immutable field PERMISSION_DENIED  caller may not modify it`, Groups_UpdateGroupSchemaJSON, Groups_UpdateGroupOutputSchemaJSON, nil, "", nil)
)

